def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    dangerous_prev = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) >= DAILY_SALARY * 0.8:
                    dangerous_prev.append(float(bid))

    if not alive:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency += 40.0
    elif hp <= 4:
        urgency += 24.0
    elif hp <= 6:
        urgency += 10.0

    if no_water >= 2:
        urgency += 28.0
    elif no_water >= 1:
        urgency += 12.0

    urgency += scarcity * 12.0

    if hp >= 7 and no_water == 0 and highest_prev >= 90.0:
        return float(min(budget, 9.0))

    if hp >= 5 and no_water == 0 and highest_prev >= 105.0:
        return float(min(budget, 7.0))

    base = 32.0 + urgency

    if highest_prev > 0:
        if hp <= 3 or no_water >= 2:
            bid = max(base, highest_prev + 2.5)
        elif hp <= 5 or no_water >= 1:
            bid = max(base, avg_prev + 3.0)
        else:
            if highest_prev >= 95.0:
                bid = 12.0
            else:
                bid = max(base, highest_prev - 6.0)
    else:
        bid = base

    if day >= 8:
        bid += 8.0
    elif day >= 6:
        bid += 4.0

    if budget < DAILY_SALARY:
        bid = min(bid, budget * 0.82)
    elif budget < DAILY_SALARY * 2:
        bid = min(bid, budget * 0.72)
    else:
        bid = min(bid, budget * 0.58 + 18.0)

    if hp <= 2:
        bid = max(bid, min(budget, 92.0))
    elif hp <= 4 and highest_prev > 0:
        bid = max(bid, min(budget, highest_prev + 1.5))

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    hp = float(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((opp_id, o))

    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids from previous_trace (immediate reaction only)
    prev_bids = []
    for _, o in alive_opps:
        prev = o.get('previous_trace', {})
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Determine a target aggressiveness based on yesterday's pressure
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        second_prev_bid = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest_prev_bid
    else:
        highest_prev_bid = 0.0
        second_prev_bid = 0.0

    # Supply pressure: higher supply means we can bid less; lower supply means bid more to secure water
    supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)  # 0..1
    supply_norm = max(0.0, min(1.0, supply_norm))

    # Base bid: aim to outbid surviving high bidders when supply is moderate/high.
    # If supply is low, we need more water certainty -> bid closer to top bidder.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # Opponent(s) were very aggressive; try to match/just exceed when we can afford it.
        if hp > 3 and no_water_days <= 1:
            target = max(highest_prev_bid * 0.98, second_prev_bid + 2.0)
        else:
            target = max(highest_prev_bid * 1.02, second_prev_bid + 4.0)
    else:
        # Opponents not extremely aggressive; bid enough to stay competitive.
        # Lower supply -> higher bid.
        target = (DAILY_SALARY * (0.45 + 0.35 * (1.0 - supply_norm)))
        # If we saw any nontrivial bid, slightly chase it.
        if highest_prev_bid > 0:
            target = max(target, highest_prev_bid + 1.5)

    # If my hp is critical or I'm already on no-water streak, increase bid.
    if hp <= 2.0 or no_water_days >= 2:
        target *= 1.25

    # Never exceed budget; also keep below a reasonable cap to avoid bankruptcy.
    cap = max(0.0, budget)
    # Soft cap: don't exceed ~1.2*DAILY_SALARY unless budget forces it.
    soft_cap = min(cap, DAILY_SALARY * 1.2)

    bid = min(target, soft_cap)
    if bid < 0.0:
        bid = 0.0

    # Ensure we bid at least a minimal amount if we can; otherwise 0.
    min_reasonable = 1.0
    if budget >= min_reasonable:
        return float(min(max(bid, min_reasonable), cap))
    return float(max(0.0, min(bid, cap)))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])
    if yesterday_bids:
        avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids)
        target_bid = avg_prev_bid * 1.05
    else:
        target_bid = DAILY_SALARY * 0.6
    if my_status['hp'] < 4:
        return float(min(my_status['budget'], DAILY_SALARY * 1.2))
    return float(min(my_status['budget'], target_bid))
